css:
@page { size: A4; margin: 0; }
.print-format { padding: 0 !important; margin: 0 !important; max-width: none !important; width: 210mm; font-size: 10px; }
.print-format, .print-format * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; box-sizing: border-box; }

.print-format .gq { position: relative; width: 210mm; min-height: 296.9mm; padding: 0 9mm 9mm; display: flex; flex-direction: column; overflow: hidden;
	font-family: Montserrat, "Segoe UI", Arial, sans-serif; color: #1d2b3a; background: #fff; }
.print-format .gq table { border-collapse: collapse; width: 100%; }
.print-format .gq td, .print-format .gq th { vertical-align: top; padding: 0 !important; border-bottom: 0; }
.print-format .gq img { display: block; }

/* decorative corners */
.print-format .gq-corner { position: absolute; z-index: 0; }
.print-format .gq-tl { top: 0; left: 0; width: 26mm; height: 40mm; }
.print-format .gq-bl { bottom: 0; left: 0; width: 22mm; height: 28mm; }
.print-format .gq-br { bottom: 0; right: 0; width: 26mm; height: 30mm; }
.print-format .gq > *:not(.gq-corner) { position: relative; z-index: 1; }

/* ---------- header ---------- */
.print-format .gq-head { height: 39mm; margin: 0 -9mm 2.5mm; position: relative; }
.print-format .gq-banner { position: absolute; top: 0; right: 0; width: 56%; height: 100%; background-size: cover; background-position: center;
	clip-path: polygon(20% 0, 100% 0, 100% 100%, 0 100%); }
.print-format .gq-flag { position: absolute; top: 0; right: 0; width: 31mm; height: 31mm; background: #0b3a66; color: #fff;
	padding: 4mm 3mm 0 6mm; clip-path: polygon(16% 0, 100% 0, 100% 100%, 0 100%); }
.print-format .gq-flag-big { font-size: 11.5px; font-weight: 800; line-height: 1.25; letter-spacing: .3px; }
.print-format .gq-flag-line { width: 12mm; height: 2px; background: #8cc63f; margin-top: 3mm; }
.print-format .gq-brand { position: absolute; left: 12mm; top: 5mm; width: 88mm; }
.print-format .gq-logo { width: 25mm; padding-right: 3mm !important; vertical-align: middle !important; }
.print-format .gq-logo img { width: 21mm; height: 21mm; object-fit: contain; }
.print-format .gq-brand td { vertical-align: middle; }
.print-format .gq-cname { font-size: 25px; font-weight: 900; color: #0b3a66; line-height: 1; letter-spacing: -.5px; text-transform: uppercase; }
.print-format .gq-csub { font-size: 10.5px; font-weight: 800; color: #1f8f3a; margin-top: 2px; text-transform: uppercase; letter-spacing: .3px; }
.print-format .gq-tagline { font-size: 7.5px; font-weight: 600; letter-spacing: 1.6px; color: #1d2b3a; margin-top: 2mm; white-space: nowrap; }

/* ---------- main two-column ---------- */
.print-format .gq-main > tbody > tr > td.gq-left { width: 72%; padding-right: 4mm; }
.print-format .gq-main > tbody > tr > td.gq-right { width: 28%; }

.print-format .gq-top { margin-bottom: 2.5mm; }
.print-format .gq-cust { width: 47%; padding-right: 4mm !important; border-right: 1px solid #dbe3ea; }
.print-format .gq-badge { width: 11mm; }
.print-format .gq-badge svg { background: #0b3a66; border-radius: 50%; padding: 6px; width: 34px; height: 34px; }
.print-format .gq-h { font-size: 13px; font-weight: 800; color: #0b3a66; letter-spacing: .6px; margin-bottom: 1.2mm; }
.print-format .gq-kv td { font-size: 10px; padding: 1px 0 !important; }
.print-format .gq-kv td:first-child { width: 17mm; color: #44505c; }
.print-format .gq-kv td:nth-child(2) { width: 4mm; }
.print-format .gq-cust-name { font-size: 13px !important; font-weight: 700; color: #0b3a66; }
.print-format .gq-desc { padding-left: 4mm !important; }
.print-format .gq-desc-ic { width: 8mm; }
.print-format .gq-h2 { font-size: 10px; font-weight: 700; color: #0b3a66; letter-spacing: .3px; vertical-align: middle !important; }
.print-format .gq-desc-box { margin-top: 1.2mm; min-height: 12mm; border: 1px solid #dbe3ea; border-radius: 6px; background: #f6f9fb; padding: 2.5mm 3mm; font-size: 10px; line-height: 1.4; }

.print-format .gq-bar { font-size: 13px !important; background: linear-gradient(90deg, #0d5c3a 0%, #1f8f3a 40%, #0b3a66 100%); color: #fff; font-weight: 800; font-size: 14px;
	letter-spacing: .6px; padding: 1.6mm 4mm; border-radius: 6px 6px 0 0; border-left: 5px solid #8cc63f; }
.print-format .gq-items { font-size: 8.1px; border: 1px solid #dbe3ea; }
.print-format .gq-items thead th { background: #0d5c3a; color: #fff; font-weight: 700; font-size: 10px; text-align: left; padding: 1.3mm 2.5mm !important; border-right: 1px solid #ffffff55; }
.print-format .gq-items td { padding: .32mm 2.2mm !important; line-height: 1.22; border-right: 1px solid #e3e9ee; }
.print-format .gq-items tbody tr:nth-child(even) td { background: #eef5f1; }
.print-format .gq-items tr { page-break-inside: avoid; }
.print-format .gq-items .c-no { width: 11mm; text-align: center !important; }
.print-format .gq-items .c-brand { width: 47mm; }
.print-format .gq-items .c-qty { width: 17mm; text-align: center !important; }

/* ---------- right column ---------- */
.print-format .gq-card { border-radius: 8px; background: #eef3f7; margin-bottom: 2.6mm; padding: 2.6mm 3mm; }
.print-format .gq-meta-ic { width: 11mm; vertical-align: middle !important; }
.print-format .gq-meta-date { margin-top: 2.5mm; border-top: 1px solid #d7e0e8; padding-top: 2mm; }
.print-format .gq-lbl { font-size: 8.5px; font-weight: 700; color: #0b3a66; letter-spacing: .5px; }
.print-format .gq-quote-no { font-size: 11.5px; font-weight: 800; color: #0b3a66; white-space: nowrap; line-height: 1.15; }
.print-format .gq-date { font-size: 12px; font-weight: 600; color: #0b3a66; }
.print-format .gq-amt { background: #f2f5f8; padding: 4mm 3mm; }
.print-format .gq-amt-ic { width: 14mm; vertical-align: middle !important; }
.print-format .gq-circle { display: inline-block; width: 12mm; height: 12mm; border-radius: 50%; background: #1f8f3a; text-align: center; padding-top: 3.2mm; }
.print-format .gq-circle svg { display: inline-block; }
.print-format .gq-circle-w { background: #fff; }
.print-format .gq-amt-lbl { font-size: 11px; font-weight: 500; line-height: 1.25; }
.print-format .gq-amt-val { font-size: 17px; font-weight: 800; margin-top: 1mm; white-space: nowrap; }
.print-format .gq-amt-dark { background: linear-gradient(135deg, #1f8f3a, #0d5c3a); color: #fff; }
.print-format .gq-rule { height: 2px; background: linear-gradient(90deg, #1f8f3a, #0b3a66); margin: 2mm 0 4mm; }
.print-format .gq-feat td { width: 20%; text-align: center; font-size: 6.6px; line-height: 1.2; color: #2b3a48; padding: 0 .5mm !important; }
.print-format .gq-feat svg { display: inline-block; margin-bottom: 1mm; }

/* ---------- notes / terms ---------- */
.print-format .gq-lower { margin-top: 3mm; page-break-inside: avoid; }
.print-format .gq-panel { width: 49%; background: #f2f5f8; border-radius: 8px; padding: 0 4mm 2mm !important; }
.print-format .gq-gap { width: 2%; }
.print-format .gq-pill { display: inline-block; background: linear-gradient(90deg, #0d5c3a, #1f8f3a 60%, #0b3a66); color: #fff; font-weight: 800; font-size: 12px;
	letter-spacing: .6px; padding: 1.3mm 9mm 1.3mm 3mm; border-radius: 0 0 16px 0; margin: 0 0 2mm -4mm; }
.print-format .gq-pill svg, .print-format .gq-pill span { vertical-align: middle; }
.print-format .gq-pill span { margin-left: 2mm; }
.print-format .gq-pill-blue { background: linear-gradient(90deg, #0d5c3a, #0b3a66); }
.print-format .gq-notes td { font-size: 8.8px; padding: .3mm 0 !important; vertical-align: middle !important; }
.print-format .gq-num { width: 8mm; }
.print-format .gq-num span { display: inline-block; width: 4.6mm; height: 4.6mm; border-radius: 50%; background: #0d5c3a; color: #fff; font-weight: 700; font-size: 9px; text-align: center; line-height: 4.6mm; }
.print-format .gq-terms { margin: 0; padding-left: 5mm; font-size: 9px; line-height: 1.4; }
.print-format .gq-terms li { margin-bottom: 1mm; }

/* ---------- signature / pay to ---------- */
.print-format .gq-sign-row { margin-top: 2mm; page-break-inside: avoid; }
.print-format .gq-sign { width: 49%; }
.print-format .gq-sign-lbl { font-size: 10px; font-weight: 800; color: #0d5c3a; letter-spacing: 1.5px; margin: 1mm 0 .5mm 8mm; }
.print-format .gq-seal { width: 27mm; padding-left: 6mm !important; vertical-align: middle !important; }
.print-format .gq-seal img { width: 21mm; height: 21mm; object-fit: contain; }
.print-format .gq-sig { vertical-align: bottom !important; padding-left: 2mm !important; }
.print-format .gq-sig img { max-width: 40mm; max-height: 14mm; object-fit: contain; }
.print-format .gq-sig-name { font-size: 12px; font-weight: 700; margin-top: 1mm; }
.print-format .gq-sig-phone { font-size: 11px; font-weight: 600; }
.print-format .gq-pay-h td { vertical-align: middle !important; font-size: 15px; font-weight: 800; color: #0b3a66; }
.print-format .gq-pay-h td:first-child { width: 12mm; }
.print-format .gq-bank { margin-left: 12mm; width: auto !important; }
.print-format .gq-bank td { font-size: 9px; padding: .2mm 0 !important; }
.print-format .gq-bank td:first-child { width: 29mm; }

/* ---------- footer ---------- */
.print-format .gq-foot { margin-top: auto; padding-top: 2mm; page-break-inside: avoid; }
.print-format .gq-offices { border-top: 1px solid #dbe3ea; margin-bottom: 2.5mm; }
.print-format .gq-offices td { font-size: 7.9px; line-height: 1.25; }
.print-format .gq-offices > tbody > tr > td { width: 33.3%; padding: 2mm 3mm 0 !important; font-size: 7.9px; line-height: 1.35; color: #2b3a48; border-left: 1px solid #c9d3dc; }
.print-format .gq-offices > tbody > tr > td.gq-off-first { border-left: none; padding-left: 0 !important; }
.print-format .gq-pin { width: 8mm; }
.print-format .gq-off-h { font-size: 9.5px; font-weight: 800; color: #0d5c3a; }
.print-format .gq-off-co { font-weight: 700; color: #1d2b3a; }
.print-format .gq-contact { background: linear-gradient(90deg, #0d5c3a, #0b3a66); border-radius: 8px; }
.print-format .gq-contact td { color: #fff; font-size: 10.5px; font-weight: 500; padding: 1.8mm 3mm !important; vertical-align: middle !important; white-space: nowrap; border-left: 1px solid #ffffff55; }
.print-format .gq-contact td:first-child { border-left: none; }
.print-format .gq-contact svg, .print-format .gq-contact span { vertical-align: middle; }
.print-format .gq-contact span { margin-left: 2mm; }

/* ---------- explicit colours ----------
   The site's print style and the browser's own print rules can override
   colours that are only inherited. Every white-on-colour text is set here
   directly so it stays white in the PDF and in browser printing. */
.print-format .gq .gq-flag, .print-format .gq .gq-flag div,
.print-format .gq .gq-bar,
.print-format .gq .gq-items thead th,
.print-format .gq .gq-amt-dark, .print-format .gq .gq-amt-dark div,
.print-format .gq .gq-pill, .print-format .gq .gq-pill span,
.print-format .gq .gq-num span,
.print-format .gq .gq-contact td, .print-format .gq .gq-contact span {
	color: #fff !important; -webkit-text-fill-color: #fff !important;
}
.print-format .gq .gq-amt:not(.gq-amt-dark) div, .print-format .gq .gq-sig-name, .print-format .gq .gq-sig-phone,
.print-format .gq .gq-notes td, .print-format .gq .gq-terms li, .print-format .gq .gq-kv td, .print-format .gq .gq-items td {
	color: #1d2b3a; -webkit-text-fill-color: currentColor;
}
.print-format .gq .gq-kv td:first-child { color: #44505c; }
.print-format .gq .gq-cust-name, .print-format .gq .gq-h, .print-format .gq .gq-h2, .print-format .gq .gq-lbl,
.print-format .gq .gq-quote-no, .print-format .gq .gq-date, .print-format .gq .gq-pay-h td, .print-format .gq .gq-cname { color: #0b3a66 !important; }
.print-format .gq .gq-csub, .print-format .gq .gq-sign-lbl, .print-format .gq .gq-off-h { color: #0d5c3a !important; }

/* ---------- extra pages (full-page images from the Print Images tab) ---------- */
.print-format .xp-brk { break-before: page; page-break-before: always; height: 0; }
.print-format .xp-page { position: relative; width: 210mm; height: 296.9mm; overflow: hidden; }
.print-format .xp-page .xp-img { width: 100%; height: 100%; object-fit: contain; display: block; }

html:
{#- ===================== Solar Quotation (Green) =====================
     Everything comes from ERPNext:
       Company     : name, logo, phone, email, website, addresses (Address linked to the Company)
       Images      : Header Image / Signature / Seal from the quotation's Print Images (button on the quotation),
                     else this print format's Image Slots defaults, else the Company fields
       Company     : Signatory, Signatory Phone, Tagline, default notes (custom fields)
       Bank Account: the company's default company bank account (Pay To)
       Quotation   : customer, address, items, notes (custom_quote_notes, else Company default notes), terms, totals, MNRE subsidy
     Optional quotation fields used when they exist on the site:
       custom_project_description, custom_print_description, custom_customer_payable,
       custom_mnre_subsidy, custom_quote_signature, custom_total_capacity, custom_roof_type, custom_solar_package
-#}
{%- macro money(v) -%}{{ cur }} {{ frappe.utils.fmt_money(v or 0, 0, None, "#,##,###.##") }}/-{%- endmacro -%}
{%- macro split_lines(text) -%}{{ (text or "") | replace("\r", "") | replace("\n", "~~") | replace("<br>", "~~") | replace("<br/>", "~~") | replace("<br />", "~~") | replace("</p>", "~~") | replace("</li>", "~~") | replace("</div>", "~~") | striptags }}{%- endmacro -%}

{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set cur = frappe.db.get_value("Currency", doc.currency, "symbol") or doc.currency -%}
{%- set logo = company.company_logo -%}
{#- images: this quotation's Print Images, else the slot default on this print format, else the Company fields -#}
{%- set img = {} -%}
{%- set _pf = frappe.get_doc("Print Format", "Solar Quotation Green") -%}
{%- for s in _pf.get("custom_image_slots") or [] -%}{%- if s.default_image -%}{%- set _ = img.update({s.label: s.default_image}) -%}{%- endif -%}{%- endfor -%}
{%- for r in doc.get("custom_print_images") or [] -%}{%- if r.print_format == _pf.name and r.image -%}{%- set _ = img.update({r.slot: r.image}) -%}{%- endif -%}{%- endfor -%}
{%- set header_img = img.get("Header Image") or company.get("custom_quote_header_image") -%}
{%- set signature = img.get("Signature") or company.get("custom_quote_signature") -%}
{%- set seal = img.get("Seal") or company.get("custom_quote_seal") -%}
{%- set signatory = company.get("custom_quote_signatory") or frappe.db.get_value("User", doc.owner, "full_name") or "" -%}
{%- set signatory_phone = company.get("custom_quote_signatory_phone") or company.phone_no or "" -%}
{%- set tagline = company.get("custom_quote_tagline") or "CLEAN ENERGY | SMART MOBILITY | BETTER TOMORROW" -%}

{#- company name: first two words large, the rest as the green sub-line -#}
{%- set cwords = (company.company_name or doc.company).split(" ") -%}
{%- set cname_main = cwords[:2] | join(" ") if cwords | length > 2 else cwords | join(" ") -%}
{%- set cname_sub = cwords[2:] | join(" ") if cwords | length > 2 else "" -%}

{#- customer address: quotation address, else the Lead's address -#}
{%- set cust_addr = (doc.address_display or "") | replace("<br>", ", ") | replace("<br/>", ", ") | striptags | trim -%}
{%- set lead = doc.get("custom_lead") or (doc.party_name if doc.quotation_to == "Lead" else None) -%}
{%- if not cust_addr and lead -%}
	{%- set la = frappe.db.get_value("Lead", lead, ["custom_address", "city", "state"], as_dict=1) or {} -%}
	{%- set cust_addr = la.get("custom_address") or ([la.get("city"), la.get("state")] | select | join(", ")) -%}
{%- endif -%}
{%- set cust_addr = cust_addr.rstrip(", ") -%}
{%- set cust_phone = doc.contact_mobile or doc.get("contact_phone") or "" -%}

{%- set description = doc.get("custom_project_description") or doc.get("custom_print_description") or "" -%}
{%- if not description and (doc.get("custom_total_capacity") or doc.get("custom_solar_package")) -%}
	{%- set description = ([doc.get("custom_total_capacity"), "Solar Power Plant", ("(" ~ doc.custom_roof_type ~ " roof)") if doc.get("custom_roof_type") else None] | select | join(" ")) -%}
{%- endif -%}

{%- set subtotal = doc.total -%}
{%- set payable = doc.get("custom_customer_payable") or doc.rounded_total or doc.grand_total -%}
{%- set subsidy = doc.get("custom_mnre_subsidy") or 0 -%}

{%- set notes = split_lines(doc.get("custom_quote_notes") or company.get("custom_quote_notes")).split("~~") | map("trim") | select | list -%}
{%- set terms = split_lines(doc.terms).split("~~") | map("trim") | select | list -%}

{%- set bank = (frappe.get_all("Bank Account",
		filters={"company": doc.company, "is_company_account": 1, "disabled": 0},
		fields=["bank", "account_name", "bank_account_no", "branch_code", "custom_branch"],
		order_by="is_default desc, creation asc", limit=1) or [None])[0] -%}
{%- set offices = frappe.get_all("Address",
		filters=[["Dynamic Link", "link_doctype", "=", "Company"], ["Dynamic Link", "link_name", "=", doc.company], ["disabled", "=", 0]],
		fields=["address_title", "address_line1", "address_line2", "city", "county", "state", "pincode"],
		order_by="is_your_company_address desc, creation asc", limit=3) -%}

{#- ---------- icons (inline SVG, 24x24 grid) ---------- -#}
{%- set I = {
	"user": '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7"/>',
	"doc": '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>',
	"cal": '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4M8 14h2M14 14h2M8 18h2M14 18h2"/>',
	"wallet": '<path d="M4 7h14a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a1 1 0 0 1-1-1z"/><path d="M4 7l11-3v3"/><circle cx="16" cy="13.5" r="1.2"/>',
	"pct": '<path d="M19 5 5 19"/><circle cx="7" cy="7" r="2.5"/><circle cx="17" cy="17" r="2.5"/>',
	"bolt": '<path d="M13 2 4 14h7l-1 8 9-12h-7z"/>',
	"leaf": '<path d="M5 19c0-9 6-14 15-14 0 9-5 15-14 15"/><path d="M5 19c3-4 6-6 10-8"/>',
	"gear": '<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M2 12h3M19 12h3M4.9 19.1 7 17M17 7l2.1-2.1"/>',
	"bars": '<path d="M5 20v-5M10 20v-9M15 20V7M20 20V3"/>',
	"shield": '<path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',
	"bank": '<path d="M3 10 12 4l9 6M5 10v8M9 10v8M15 10v8M19 10v8M3 21h18"/>',
	"pin": '<path d="M12 21s-7-6.2-7-12a7 7 0 0 1 14 0c0 5.8-7 12-7 12z"/><circle cx="12" cy="9" r="2.5"/>',
	"phone": '<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>',
	"mail": '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
	"globe": '<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.5 2.6 3.8 5.6 3.8 9s-1.3 6.4-3.8 9c-2.5-2.6-3.8-5.6-3.8-9S9.5 5.6 12 3"/>'
} -%}
{%- macro ic(name, size=18, color="currentColor", sw=2) -%}<svg width="{{ size }}" height="{{ size }}" viewBox="0 0 24 24" fill="none" stroke="{{ color }}" stroke-width="{{ sw }}" stroke-linecap="round" stroke-linejoin="round">{{ I[name] }}</svg>{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">

{%- macro _content() -%}
<div class="gq">
	{#- decorative corners -#}
	<svg class="gq-corner gq-tl" viewBox="0 0 100 100" preserveAspectRatio="none"><polygon points="0,0 100,0 0,100" fill="#2e9e44"/><polygon points="0,0 60,0 0,60" fill="#8cc63f"/></svg>
	<svg class="gq-corner gq-bl" viewBox="0 0 100 100" preserveAspectRatio="none"><polygon points="0,0 100,100 0,100" fill="#2e9e44"/><polygon points="0,45 55,100 0,100" fill="#8cc63f"/></svg>
	<svg class="gq-corner gq-br" viewBox="0 0 100 100" preserveAspectRatio="none"><polygon points="100,0 100,100 0,100" fill="#0d5c3a"/><polygon points="100,40 100,100 40,100" fill="#8cc63f"/></svg>

	{#- ================= HEADER ================= -#}
	<div class="gq-head">
		{%- if header_img -%}<div class="gq-banner" style="background-image:url('{{ header_img }}')"></div>{%- endif -%}
		<div class="gq-flag">
			<div class="gq-flag-big">CLEAN</div>
			<div class="gq-flag-big">ENERGY</div>
			<div class="gq-flag-big">BRIGHTER</div>
			<div class="gq-flag-big">TOMORROW</div>
			<div class="gq-flag-line"></div>
		</div>
		<div class="gq-brand">
			<table><tr>
				{%- if logo -%}<td class="gq-logo"><img src="{{ logo }}"></td>{%- endif -%}
				<td>
					<div class="gq-cname">{{ cname_main }}</div>
					{%- if cname_sub -%}<div class="gq-csub">{{ cname_sub }}</div>{%- endif -%}
				</td>
			</tr></table>
			<div class="gq-tagline">{{ tagline | replace("|", "&nbsp;&nbsp;|&nbsp;&nbsp;") }}</div>
		</div>
	</div>

	{#- ================= BODY: left content + right summary ================= -#}
	<table class="gq-main"><tr>
		<td class="gq-left">
			<table class="gq-top"><tr>
				<td class="gq-cust">
					<table><tr>
						<td class="gq-badge">{{ ic("user", 20, "#fff") }}</td>
						<td>
							<div class="gq-h">CUSTOMER DETAILS</div>
							<table class="gq-kv">
								<tr><td>Name</td><td>:</td><td class="gq-cust-name">{{ doc.customer_name or doc.party_name }}</td></tr>
								<tr><td>Address</td><td>:</td><td>{{ cust_addr or "…" }}</td></tr>
								{%- if cust_phone -%}<tr><td>Phone</td><td>:</td><td>{{ cust_phone }}</td></tr>{%- endif -%}
							</table>
						</td>
					</tr></table>
				</td>
				<td class="gq-desc">
					<table><tr><td class="gq-desc-ic">{{ ic("doc", 20, "#0d5c3a") }}</td><td class="gq-h2">QUOTE / PROJECT DESCRIPTION</td></tr></table>
					<div class="gq-desc-box">{{ description }}</div>
				</td>
			</tr></table>

			<div class="gq-bar">ITEMS &amp; DESCRIPTION</div>
			<table class="gq-items">
				<thead><tr><th class="c-no">S.No</th><th>Item &amp; Description</th><th class="c-brand">Brand</th><th class="c-qty">Quantity</th></tr></thead>
				<tbody>
				{%- for it in doc.items -%}
					{%- set q = it.qty | int if it.qty == (it.qty | int) else it.qty -%}
					<tr>
						<td class="c-no">{{ loop.index }}</td>
						<td>{{ (it.item_name or it.item_code) | upper }}</td>
						<td class="c-brand">{{ (it.brand or "") | upper }}</td>
						<td class="c-qty">{{ q }}{% if it.qty > 1 and it.uom %} {{ it.uom | upper }}{% endif %}</td>
					</tr>
				{%- endfor -%}
				</tbody>
			</table>
		</td>

		<td class="gq-right">
			<div class="gq-card gq-meta">
				<table><tr><td class="gq-meta-ic">{{ ic("doc", 26, "#0b3a66") }}</td><td><div class="gq-lbl">QUOTE NO.</div><div class="gq-quote-no">{{ doc.name }}</div></td></tr></table>
				<table class="gq-meta-date"><tr><td class="gq-meta-ic">{{ ic("cal", 24, "#0b3a66") }}</td><td><div class="gq-lbl">DATE</div><div class="gq-date">{{ frappe.utils.formatdate(doc.transaction_date, "dd/MM/yyyy") }}</div></td></tr></table>
			</div>

			<div class="gq-card gq-amt">
				<table><tr><td class="gq-amt-ic"><span class="gq-circle">{{ ic("doc", 22, "#fff") }}</span></td>
				<td><div class="gq-amt-lbl">Sub-Total</div><div class="gq-amt-val">{{ money(subtotal) }}</div></td></tr></table>
			</div>

			<div class="gq-card gq-amt gq-amt-dark">
				<table><tr><td class="gq-amt-ic"><span class="gq-circle gq-circle-w">{{ ic("wallet", 22, "#0d5c3a") }}</span></td>
				<td><div class="gq-amt-lbl">Customer<br>Payable Amount</div><div class="gq-amt-val">{{ money(payable) }}</div></td></tr></table>
			</div>

			{%- if subsidy -%}
			<div class="gq-card gq-amt">
				<table><tr><td class="gq-amt-ic"><span class="gq-circle">{{ ic("pct", 22, "#fff") }}</span></td>
				<td><div class="gq-amt-lbl">Available<br>MNRE Subsidy</div><div class="gq-amt-val">{{ money(subsidy) }}</div></td></tr></table>
			</div>
			{%- endif -%}

			<div class="gq-rule"></div>
			<table class="gq-feat"><tr>
				{%- for f in [("bolt", "Reliable Performance"), ("leaf", "Lower Electricity Bills"), ("gear", "Professional Installation"), ("bars", "Long Term Savings"), ("shield", "Sustainable Future")] -%}
				<td>{{ ic(f[0], 22, "#1f8f3a", 2.4) }}<div>{{ f[1] }}</div></td>
				{%- endfor -%}
			</tr></table>
		</td>
	</tr></table>

	{#- ================= NOTES / TERMS (only when there is something to show) ================= -#}
	{%- if notes or terms -%}
	<table class="gq-lower"><tr>
		{%- if notes -%}
		<td class="gq-panel">
			<div class="gq-pill">{{ ic("doc", 16, "#fff") }}<span>NOTES</span></div>
			<table class="gq-notes">
			{%- for n in notes -%}<tr><td class="gq-num"><span>{{ loop.index }}</span></td><td>{{ n }}</td></tr>{%- endfor -%}
			</table>
		</td>
		{%- endif -%}
		{%- if notes and terms -%}<td class="gq-gap"></td>{%- endif -%}
		{%- if terms -%}
		<td class="gq-panel">
			<div class="gq-pill gq-pill-blue">{{ ic("doc", 16, "#fff") }}<span>TERMS &amp; CONDITIONS</span></div>
			<ul class="gq-terms">
			{%- for t in terms -%}<li>{{ t }}</li>{%- endfor -%}
			</ul>
		</td>
		{%- endif -%}
		{%- if not (notes and terms) -%}<td class="gq-gap" style="width:51%"></td>{%- endif -%}
	</tr></table>
	{%- endif -%}

	{#- ================= SIGNATURE / PAY TO ================= -#}
	<table class="gq-sign-row"><tr>
		<td class="gq-sign">
			<div class="gq-sign-lbl">SIGNATURE</div>
			<table><tr>
				{%- if seal -%}<td class="gq-seal"><img src="{{ seal }}"></td>{%- endif -%}
				<td class="gq-sig">
					{%- if signature -%}<img src="{{ signature }}">{%- endif -%}
					<div class="gq-sig-name">{{ signatory }}</div>
					{%- if signatory_phone -%}<div class="gq-sig-phone">{{ signatory_phone }}</div>{%- endif -%}
				</td>
			</tr></table>
		</td>
		<td class="gq-gap"></td>
		<td class="gq-pay">
			{%- if bank -%}
			<table class="gq-pay-h"><tr><td>{{ ic("bank", 34, "#0b3a66", 2.2) }}</td><td>PAY TO :</td></tr></table>
			<table class="gq-kv gq-bank">
				<tr><td>Bank</td><td>:</td><td>{{ (bank.bank or "") | upper }}</td></tr>
				{%- if bank.custom_branch -%}<tr><td>Branch</td><td>:</td><td>{{ bank.custom_branch | upper }}</td></tr>{%- endif -%}
				<tr><td>Account Name</td><td>:</td><td>{{ (bank.account_name or company.company_name) | upper }}</td></tr>
				<tr><td>ACC No</td><td>:</td><td>{{ bank.bank_account_no or "" }}</td></tr>
				{%- if bank.branch_code -%}<tr><td>IFSC</td><td>:</td><td>{{ bank.branch_code | upper }}</td></tr>{%- endif -%}
			</table>
			{%- endif -%}
		</td>
	</tr></table>

	{#- ================= FOOTER ================= -#}
	<div class="gq-foot">
		{%- if offices -%}
		<table class="gq-offices"><tr>
			{%- for a in offices -%}
			<td class="{{ 'gq-off-first' if loop.first else '' }}">
				<table><tr>
					{%- if loop.first -%}<td class="gq-pin">{{ ic("pin", 24, "#1f8f3a", 2.4) }}</td>{%- endif -%}
					<td>
						<div class="gq-off-h">{{ (a.address_title or "Office") | upper }}</div>
						{%- if loop.first -%}<div class="gq-off-co">{{ company.company_name | upper }}</div>{%- endif -%}
						<div>{{ ([a.address_line1, a.address_line2] | select | join(", ")) | upper }}</div>
						<div>{{ ([a.city, a.county] | select | join(", ")) | upper }}</div>
						<div>{{ ([a.state, a.pincode] | select | join(" - ")) | upper }}</div>
					</td>
				</tr></table>
			</td>
			{%- endfor -%}
		</tr></table>
		{%- endif -%}
		<table class="gq-contact"><tr>
			{%- if company.phone_no -%}<td>{{ ic("phone", 18, "#fff") }}<span>{{ company.phone_no }}</span></td>{%- endif -%}
			{%- if signatory -%}<td>{{ ic("user", 18, "#fff") }}<span>{{ signatory }}</span></td>{%- endif -%}
			{%- if company.email -%}<td>{{ ic("mail", 18, "#fff") }}<span>{{ company.email }}</span></td>{%- endif -%}
			{%- if company.website -%}<td>{{ ic("globe", 18, "#fff") }}<span>{{ company.website | replace("https://", "") | replace("http://", "") }}</span></td>{%- endif -%}
		</tr></table>
	</div>
</div>

{%- endmacro -%}

{#- ================= EXTRA PAGES =================
    Full-page images from the Print Images tab (defaults on this Print Format's Extra Pages table,
    replaced or skipped per quotation). Each prints at its page number; the quotation page above
    takes the first free number. -#}
{%- set _xm = {} -%}
{%- for p in _pf.get("custom_extra_pages") or [] -%}{%- if p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- for p in doc.get("custom_print_extra_pages") or [] -%}{%- if p.print_format == _pf.name and p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- set _xl = [] -%}
{%- for k in _xm.keys()|sort -%}{%- if _xm[k] -%}{%- set _ = _xl.append([k, _xm[k]]) -%}{%- endif -%}{%- endfor -%}
{%- set _xn = namespace(b=0, x=0, pos=1) -%}
{%- for _i in range(1 + _xl|length) -%}
{%- if not loop.first -%}<div class="xp-brk"></div>{%- endif -%}
{%- if _xn.x < _xl|length and (_xl[_xn.x][0] <= _xn.pos or _xn.b >= 1) -%}
<div class="xp-page"><img class="xp-img" src="{{ _xl[_xn.x][1] }}"></div>
{%- set _xn.x = _xn.x + 1 -%}
{%- else -%}
{{ _content() }}
{%- set _xn.b = _xn.b + 1 -%}
{%- endif -%}
{%- set _xn.pos = _xn.pos + 1 -%}
{%- endfor -%}

css:
@page { size: A4; margin: 0; }
.print-format { padding: 0 !important; margin: 0 !important; max-width: none !important; width: 210mm; font-size: 10px; }
.print-format, .print-format * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; box-sizing: border-box; }

.print-format .gc { position: relative; width: 210mm; min-height: 296.9mm; padding: 0 8mm 6mm; display: flex; flex-direction: column; overflow: hidden;
	font-family: Montserrat, "Segoe UI", Arial, sans-serif; color: #1d2b3a; background: #fff; }
.print-format .gc table { border-collapse: collapse; width: 100%; }
.print-format .gc td, .print-format .gc th { vertical-align: top; padding: 0 !important; border: 0; }
.print-format .gc img { display: block; }
.print-format .gc > *:not(.gc-leaf) { position: relative; z-index: 1; }

/* leaves */
.print-format .gc .gc-leaf { position: absolute; z-index: 0; opacity: .85; }
.print-format .gc .gc-l1 { width: 22mm; height: 22mm; left: -6mm; top: -4mm; transform: rotate(-20deg); }
.print-format .gc .gc-l2 { width: 16mm; height: 16mm; left: -5mm; bottom: 48mm; transform: rotate(-60deg); opacity: .55; }
.print-format .gc .gc-l3 { width: 18mm; height: 18mm; right: -5mm; bottom: 70mm; transform: rotate(150deg); opacity: .6; }
.print-format .gc .gc-l4 { width: 20mm; height: 20mm; right: -4mm; bottom: -4mm; transform: rotate(80deg); opacity: .7; }

/* ---------- header ---------- */
.print-format .gc .gc-head { height: 58mm; margin: 0 -8mm; position: relative; }
.print-format .gc .gc-banner { position: absolute; top: 0; right: 0; width: 52%; height: 60mm; background-size: cover; background-position: center;
	-webkit-mask-image: linear-gradient(90deg, transparent 0, #000 22%); mask-image: linear-gradient(90deg, transparent 0, #000 22%); }
.print-format .gc .gc-flag { position: absolute; top: 8mm; right: 5mm; border-left: 2.5px solid #1f8f3a; padding-left: 2.5mm;
	font-size: 12px; font-weight: 800; line-height: 1.2; letter-spacing: .4px; background: rgba(255,255,255,.82); padding: 1.5mm 2.5mm; border-radius: 0 4px 4px 0; }
.print-format .gc .gc-brand { position: absolute; left: 11mm; top: 8mm; width: 100mm; }
.print-format .gc .gc-logo { width: 32mm; padding-right: 3mm !important; vertical-align: middle !important; }
.print-format .gc .gc-logo img { width: 29mm; height: 29mm; object-fit: contain; }
.print-format .gc .gc-names { vertical-align: middle !important; }
.print-format .gc .gc-cname { font-size: 31px; font-weight: 900; line-height: .95; letter-spacing: -.5px; text-transform: uppercase; }
.print-format .gc .gc-csub { font-size: 11.5px; font-weight: 800; margin-top: 3px; text-transform: uppercase; letter-spacing: .6px; }
.print-format .gc .gc-tagline { font-size: 7.5px; font-weight: 600; letter-spacing: 1.8px; margin-top: 3mm; white-space: nowrap; }
.print-format .gc .gc-badges { margin-top: 5mm; width: auto !important; }
.print-format .gc .gc-badges > tbody > tr > td { padding-right: 2.2mm !important; border-right: 1px solid #cfd8d2 !important; }
.print-format .gc .gc-badges > tbody > tr > td + td { padding-left: 2.2mm !important; }
.print-format .gc .gc-badges > tbody > tr > td:last-child { border-right: 0 !important; }
.print-format .gc .gc-b-ic { width: 8mm; vertical-align: middle !important; }
.print-format .gc .gc-b-tx { font-size: 6.6px; font-weight: 600; line-height: 1.2; text-transform: uppercase; vertical-align: middle !important; white-space: nowrap; }

/* ---------- info row ---------- */
.print-format .gc .gc-info { margin-top: 1mm; }
.print-format .gc .gc-cust { width: 39%; padding-top: 3mm !important; }
.print-format .gc .gc-badge { width: 13mm; }
.print-format .gc .gc-badge svg { background: #1f8f3a; border-radius: 50%; padding: 7px; width: 38px; height: 38px; }
.print-format .gc .gc-h { font-size: 12.5px; font-weight: 800; letter-spacing: 1.2px; margin-bottom: 2mm; }
.print-format .gc .gc-kv td { font-size: 10.5px; padding: .4mm 0 !important; line-height: 1.3; }
.print-format .gc .gc-kv td:first-child { width: 16mm; }
.print-format .gc .gc-kv td:nth-child(2) { width: 4mm; }
.print-format .gc .gc-cust-name { font-weight: 700; }
.print-format .gc .gc-date { margin-top: 3.5mm; width: auto !important; }
.print-format .gc .gc-date td { vertical-align: middle !important; font-size: 13px; font-weight: 700; }
.print-format .gc .gc-date-ic { width: 12mm; }
.print-format .gc .gc-date-l { padding-right: 4mm !important; }
.print-format .gc .gc-date-c { padding-right: 3mm !important; }
.print-format .gc .gc-desc { width: 40%; padding: 3.5mm 4mm 0 2mm !important; }
.print-format .gc .gc-desc-box { border: 1px solid #b9c7cf; border-radius: 6px; min-height: 24mm; padding: 0 3mm 2.5mm; position: relative; }
.print-format .gc .gc-desc-h { font-size: 9.5px; font-weight: 700; letter-spacing: .3px; background: #fff; display: inline-block; padding: 0 2mm 0 0; margin: -2.4mm 0 1.5mm -1mm; }
.print-format .gc .gc-desc-ic { display: inline-block; vertical-align: middle; margin-right: 2mm; }
.print-format .gc .gc-desc-ic svg { display: inline-block; }
.print-format .gc .gc-desc-tx { font-size: 10px; line-height: 1.45; }
.print-format .gc .gc-qno-cell { width: 21%; }
.print-format .gc .gc-qno { margin-right: -8mm; height: 34mm; background: linear-gradient(160deg, #0d4d4a, #0b3a46 70%, #0d5c3a); padding: 7mm 3mm 0 6mm; text-align: center;
	clip-path: polygon(16% 0, 100% 0, 100% 100%, 0 100%, 0 13%); }
.print-format .gc .gc-qno-l { font-size: 11px; font-weight: 600; letter-spacing: .6px; }
.print-format .gc .gc-qno-v { font-size: 19px; font-weight: 800; margin-top: 1mm; line-height: 1.15; word-break: break-all; }
.print-format .gc .gc-qno-v.gc-qno-long { font-size: 12.5px; }
.print-format .gc .gc-qno-line { width: 13mm; height: 2px; background: #8cc63f; margin: 3mm auto 0; }

/* ---------- description bar ---------- */
.print-format .gc .gc-bar { margin-top: 3mm; background: linear-gradient(90deg, #1f8f3a 0%, #0d5c3a 45%, #0b3a66 100%); border-radius: 0 7px 7px 0; }
.print-format .gc .gc-bar td { font-size: 14px; font-weight: 700; letter-spacing: .4px; padding: 2.6mm 9mm !important; vertical-align: middle !important; }
.print-format .gc .gc-bar .gc-bar-r { text-align: right; width: 38%; padding-right: 4mm !important; border-left: 1px solid #8cc63f !important; }

.print-format .gc .gc-main { margin-top: 3.5mm; }
.print-format .gc .gc-left { width: 55%; padding: 0 5mm 0 4mm !important; border-right: 1px solid #d5dde3 !important; }
.print-format .gc .gc-title { font-size: 15.5px; font-weight: 800; line-height: 1.32; letter-spacing: .2px; min-height: 12mm; }
.print-format .gc .gc-feat { margin-top: 4mm; }
.print-format .gc .gc-feat td { width: 25%; font-size: 8.5px; line-height: 1.25; padding: 0 2mm !important; border-left: 1px solid #dfe5e9 !important; }
.print-format .gc .gc-feat td:first-child { border-left: 0 !important; padding-left: 0 !important; }
.print-format .gc .gc-feat-ic { display: inline-block; width: 10mm; height: 10mm; border-radius: 50%; background: #e7f3e3; text-align: center; padding-top: 2mm; margin-bottom: 1.5mm; }
.print-format .gc .gc-feat-ic svg { display: inline-block; }
.print-format .gc .gc-right { width: 45%; padding-left: 7mm !important; }
.print-format .gc .gc-sub { background: #f1f4f7; border-radius: 6px; }
.print-format .gc .gc-sub td:first-child, .print-format .gc .gc-pay td:first-child { white-space: nowrap; }
.print-format .gc .gc-sub td { font-size: 14px; padding: 4.5mm 3mm 4.5mm 9mm !important; vertical-align: middle !important; }
.print-format .gc .gc-c { width: 5mm; padding-left: 0 !important; padding-right: 0 !important; }
.print-format .gc .gc-v { text-align: right; font-weight: 800; white-space: nowrap; padding-left: 1mm !important; }
.print-format .gc .gc-sub .gc-v { font-size: 20px; }
.print-format .gc .gc-pay { background: #e1efc2; border-radius: 6px; margin-top: 2mm; }
.print-format .gc .gc-pay td { font-size: 9.2px; font-weight: 700; padding: 3.2mm 3mm 3.2mm 4mm !important; vertical-align: middle !important; }
.print-format .gc .gc-pay tr:first-child td { padding-top: 5mm !important; }
.print-format .gc .gc-pay tr:last-child td { padding-bottom: 5mm !important; }
.print-format .gc .gc-pay .gc-v { font-size: 16px; }

/* ---------- signature / thanks ---------- */
.print-format .gc .gc-sign-row { margin-top: 4mm; }
.print-format .gc .gc-sign { width: 47%; padding-left: 3mm !important; }
.print-format .gc .gc-sign-lbl { font-size: 10px; font-weight: 800; letter-spacing: 1.8px; margin-bottom: .5mm; }
.print-format .gc .gc-seal { width: 28mm; vertical-align: middle !important; padding-left: 2mm !important; }
.print-format .gc .gc-seal img { width: 24mm; height: 24mm; object-fit: contain; }
.print-format .gc .gc-sig { vertical-align: bottom !important; padding-left: 1mm !important; }
.print-format .gc .gc-sig img { max-width: 44mm; max-height: 14mm; object-fit: contain; }
.print-format .gc .gc-sig-name { font-size: 12.5px; font-weight: 700; margin-top: 1mm; }
.print-format .gc .gc-sig-phone { font-size: 12px; font-weight: 600; }
.print-format .gc .gc-thanks { border-left: 1px solid #c7d1d8 !important; text-align: center; vertical-align: middle !important; padding: 3mm 0 3mm 5mm !important; }
.print-format .gc .gc-thanks-h { font-size: 13px; font-weight: 800; letter-spacing: .4px; }
.print-format .gc .gc-thanks-t { font-size: 9.5px; margin-top: 1.5mm; }
.print-format .gc .gc-thanks-c { margin-top: 4mm; font-size: 11.5px; }
.print-format .gc .gc-thanks-c span, .print-format .gc .gc-thanks-c svg { display: inline-block; vertical-align: middle; }
.print-format .gc .gc-thanks-c b { vertical-align: middle; margin: 0 2mm; }
.print-format .gc .gc-thanks-c i { font-style: normal; color: #9aa7b1; margin: 0 2mm; vertical-align: middle; }

/* ---------- cards ---------- */
.print-format .gc .gc-cards { margin-top: 3.5mm; }
.print-format .gc .gc-card { background: #f2f5f8; border-radius: 6px; padding: 3.5mm 4mm 3mm !important; }
.print-format .gc .gc-gap { width: 2mm; }
.print-format .gc .gc-card-h td { vertical-align: middle !important; font-size: 14px; font-weight: 800; }
.print-format .gc .gc-card-ic { width: 11mm; }
.print-format .gc .gc-payto { width: 36%; }
.print-format .gc .gc-bank { margin-top: 3mm; }
.print-format .gc .gc-bank td { font-size: 9.6px; padding: .9mm 0 !important; line-height: 1.3; }
.print-format .gc .gc-bank td:first-child { width: 25mm; }
.print-format .gc .gc-bank td:nth-child(2) { width: 4mm; }
.print-format .gc .gc-qr { width: 22%; background: #fff; border: 1px solid #dfe5e9; text-align: center; padding: 0 0 2.5mm !important; overflow: hidden; }
.print-format .gc .gc-qr-bank { background: #1d6fb8; font-size: 11px; font-weight: 700; padding: 1.8mm 2mm !important; border-radius: 5px 5px 0 0; }
.print-format .gc .gc-qr-h { font-size: 10px; font-weight: 800; margin: 1.5mm 0 1mm; }
.print-format .gc .gc-qr-img { width: 30mm; height: 30mm; object-fit: contain; margin: 0 auto; }
.print-format .gc .gc-qr-upi { font-size: 7.6px; font-weight: 700; margin-top: 1mm; }
.print-format .gc .gc-qr-brand { font-size: 12px; font-weight: 900; font-style: italic; margin-top: 1mm; letter-spacing: .5px; }
.print-format .gc .gc-qr-brand span { color: #f47a20; font-style: normal; }
.print-format .gc .gc-notes ul { margin: 2.5mm 0 0; padding-left: 4.5mm; }
.print-format .gc .gc-notes li { font-size: 8.4px; line-height: 1.28; margin-bottom: .8mm; }
.print-format .gc .gc-notes li::marker { color: #0d5c3a; }

/* ---------- footer ---------- */
.print-format .gc .gc-foot { margin-top: auto; padding-top: 3mm; }
.print-format .gc .gc-offices { border-top: 1px solid #c9d3dc; margin-bottom: 2.5mm; }
.print-format .gc .gc-offices td { font-size: 8.3px; line-height: 1.35; }
.print-format .gc .gc-offices > tbody > tr > td { width: 33.3%; padding: 2.5mm 4mm 0 !important; font-size: 8.3px; line-height: 1.35; border-left: 1px solid #c9d3dc !important; }
.print-format .gc .gc-offices > tbody > tr > td.gc-off-first { border-left: 0 !important; padding-left: 3mm !important; }
.print-format .gc .gc-pin { width: 9mm; }
.print-format .gc .gc-off-h { font-size: 9.5px; font-weight: 800; margin-bottom: .5mm; }
.print-format .gc .gc-off-co { font-weight: 800; font-size: 8px; }
.print-format .gc .gc-contact { background: linear-gradient(90deg, #0b2f3a, #0b3a46); border-radius: 10px; }
.print-format .gc .gc-contact td { font-size: 11px; font-weight: 500; padding: 3.2mm 4mm !important; vertical-align: middle !important; white-space: nowrap; border-left: 1px solid #ffffff55 !important; }
.print-format .gc .gc-contact td:first-child { border-left: 0 !important; padding-left: 7mm !important; }
.print-format .gc .gc-contact svg, .print-format .gc .gc-contact span { display: inline-block; vertical-align: middle; }
.print-format .gc .gc-contact span { margin-left: 2.5mm; }

/* ---------- explicit colours (site print style / browser printing safe) ---------- */
.print-format .gc, .print-format .gc td, .print-format .gc div, .print-format .gc li, .print-format .gc span, .print-format .gc b { color: #1d2b3a; -webkit-text-fill-color: currentColor; }
.print-format .gc .gc-cname, .print-format .gc .gc-flag div, .print-format .gc .gc-desc-h, .print-format .gc .gc-kv td.gc-cust-name { color: #0b3a66 !important; }
.print-format .gc .gc-csub, .print-format .gc .gc-h, .print-format .gc .gc-sign-lbl, .print-format .gc .gc-thanks-h,
.print-format .gc .gc-off-h, .print-format .gc .gc-date-ic + td, .print-format .gc .gc-card-h td, .print-format .gc .gc-title { color: #0d5c3a !important; }
.print-format .gc .gc-title { color: #0b3a46 !important; }
.print-format .gc .gc-card-h td, .print-format .gc .gc-qr-h { color: #0b3a46 !important; }
.print-format .gc .gc-qr-brand { color: #0b3a66 !important; }
.print-format .gc .gc-qr-brand span { color: #f47a20 !important; }
.print-format .gc .gc-thanks-c i { color: #9aa7b1 !important; }
.print-format .gc .gc-qno div, .print-format .gc .gc-bar td, .print-format .gc .gc-qr-bank,
.print-format .gc .gc-contact td, .print-format .gc .gc-contact span { color: #fff !important; -webkit-text-fill-color: #fff !important; }

/* ---------- extra pages (full-page images from the Print Images tab) ---------- */
.print-format .xp-brk { break-before: page; page-break-before: always; height: 0; }
.print-format .xp-page { position: relative; width: 210mm; height: 296.9mm; overflow: hidden; }
.print-format .xp-page .xp-img { width: 100%; height: 100%; object-fit: contain; display: block; }

html:
{#- ================= Solar Quotation (Green Compact) =================
     One-page summary quotation. Everything comes from ERPNext:
       Company     : name, logo, phone, email, website, addresses, Signatory, Signatory Phone,
                     Tagline, UPI ID, default notes (custom fields)
       Images      : Header Image / Signature / Seal / Payment QR from the quotation's Print Images tab,
                     else this print format's Image Slots defaults, else the Company fields
       Bank Account: the company's default company bank account (Pay To)
       Quotation   : customer, address, solar package (title), description, totals, MNRE subsidy,
                     notes (Notes box, else Company default notes), terms
-#}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, 0, None, "#,##,###.##") }} /-{%- endmacro -%}
{%- macro split_lines(text) -%}{{ (text or "") | replace("\r", "") | replace("\n", "~~") | replace("<br>", "~~") | replace("<br/>", "~~") | replace("<br />", "~~") | replace("</p>", "~~") | replace("</li>", "~~") | replace("</div>", "~~") | striptags }}{%- endmacro -%}

{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set logo = company.company_logo -%}
{%- set img = {} -%}
{%- set _pf = frappe.get_doc("Print Format", "Solar Quotation Green Compact") -%}
{%- for s in _pf.get("custom_image_slots") or [] -%}{%- if s.default_image -%}{%- set _ = img.update({s.label: s.default_image}) -%}{%- endif -%}{%- endfor -%}
{%- for r in doc.get("custom_print_images") or [] -%}{%- if r.print_format == _pf.name and r.image -%}{%- set _ = img.update({r.slot: r.image}) -%}{%- endif -%}{%- endfor -%}
{%- set header_img = img.get("Header Image") or company.get("custom_quote_header_image") -%}
{%- set signature = img.get("Signature") or company.get("custom_quote_signature") -%}
{%- set seal = img.get("Seal") or company.get("custom_quote_seal") -%}
{%- set qr = img.get("Payment QR") -%}
{%- set upi = company.get("custom_quote_upi_id") or "" -%}
{%- set signatory = company.get("custom_quote_signatory") or frappe.db.get_value("User", doc.owner, "full_name") or "" -%}
{%- set signatory_phone = company.get("custom_quote_signatory_phone") or company.phone_no or "" -%}
{%- set tagline = company.get("custom_quote_tagline") or "CLEAN ENERGY | SMART MOBILITY | BETTER TOMORROW" -%}

{%- set cwords = (company.company_name or doc.company).split(" ") -%}
{%- set cname_main = cwords[:2] | join(" ") if cwords | length > 2 else cwords | join(" ") -%}
{%- set cname_sub = cwords[2:] | join(" ") if cwords | length > 2 else "" -%}

{#- customer address lines: quotation address, else the Lead's address -#}
{%- set addr_lines = ((doc.address_display or "") | replace("<br/>", "<br>") | replace("<br />", "<br>")).split("<br>") | map("striptags") | map("trim") | select | list -%}
{%- set lead = doc.get("custom_lead") or (doc.party_name if doc.quotation_to == "Lead" else None) -%}
{%- if not addr_lines and lead -%}
	{%- set la = frappe.db.get_value("Lead", lead, ["custom_address", "city", "state"], as_dict=1) or {} -%}
	{%- set addr_lines = [la.get("custom_address"), ([la.get("city"), la.get("state")] | select | join(", ")) if not la.get("custom_address") else None] | select | list -%}
{%- endif -%}
{%- set addr_lines = addr_lines[:4] -%}

{%- set description = doc.get("custom_project_description") or doc.get("custom_print_description") or "" -%}
{%- set title = doc.get("custom_solar_package") or ((doc.items[0].item_name or doc.items[0].item_code) if doc.items else "") -%}
{%- if not description and doc.get("custom_total_capacity") -%}
	{%- set description = ([doc.get("custom_total_capacity"), "Solar Power Plant", ("(" ~ doc.custom_roof_type ~ " roof)") if doc.get("custom_roof_type") else None] | select | join(" ")) -%}
{%- endif -%}

{%- set subtotal = doc.total -%}
{%- set payable = doc.get("custom_customer_payable") or doc.rounded_total or doc.grand_total -%}
{%- set subsidy = doc.get("custom_mnre_subsidy") or 0 -%}

{%- set notes = split_lines(doc.get("custom_quote_notes") or company.get("custom_quote_notes")).split("~~") | map("trim") | select | list -%}
{%- set terms = split_lines(doc.terms).split("~~") | map("trim") | select | list -%}

{%- set bank = (frappe.get_all("Bank Account",
		filters={"company": doc.company, "is_company_account": 1, "disabled": 0},
		fields=["bank", "account_name", "bank_account_no", "branch_code", "custom_branch"],
		order_by="is_default desc, creation asc", limit=1) or [None])[0] -%}
{%- set offices = frappe.get_all("Address",
		filters=[["Dynamic Link", "link_doctype", "=", "Company"], ["Dynamic Link", "link_name", "=", doc.company], ["disabled", "=", 0]],
		fields=["address_title", "address_line1", "address_line2", "city", "county", "state", "pincode"],
		order_by="is_your_company_address desc, creation asc", limit=3) -%}

{%- set I = {
	"user": '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7"/>',
	"doc": '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>',
	"cal": '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4M8 14h2M14 14h2M8 18h2M14 18h2"/>',
	"bolt": '<path d="M13 2 4 14h7l-1 8 9-12h-7z"/>',
	"leaf": '<path d="M5 19c0-9 6-14 15-14 0 9-5 15-14 15"/><path d="M5 19c3-4 6-6 10-8"/>',
	"gear": '<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M2 12h3M19 12h3M4.9 19.1 7 17M17 7l2.1-2.1"/>',
	"home": '<path d="M3 11 12 4l9 7"/><path d="M5 10v10h14V10"/><path d="M10 20v-6h4v6"/>',
	"panel": '<path d="M4 5h16l-2 10H2z"/><path d="M3 10h16M8 5 7 15M14 5l-1 10M9 15v4M6 19h7"/>',
	"plug": '<rect x="5" y="3" width="10" height="18" rx="2"/><path d="M11 7l-3 5h4l-3 5M15 9h3a1 1 0 0 1 1 1v5a2 2 0 0 0 2 2"/>',
	"bank": '<path d="M3 10 12 4l9 6M5 10v8M9 10v8M15 10v8M19 10v8M3 21h18"/>',
	"pin": '<path d="M12 21s-7-6.2-7-12a7 7 0 0 1 14 0c0 5.8-7 12-7 12z"/><circle cx="12" cy="9" r="2.5"/>',
	"phone": '<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>',
	"mail": '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
	"globe": '<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.5 2.6 3.8 5.6 3.8 9s-1.3 6.4-3.8 9c-2.5-2.6-3.8-5.6-3.8-9S9.5 5.6 12 3"/>'
} -%}
{%- macro ic(name, size=18, color="currentColor", sw=2) -%}<svg width="{{ size }}" height="{{ size }}" viewBox="0 0 24 24" fill="none" stroke="{{ color }}" stroke-width="{{ sw }}" stroke-linecap="round" stroke-linejoin="round">{{ I[name] }}</svg>{%- endmacro -%}
{%- macro leaf(cls) -%}<svg class="gc-leaf {{ cls }}" viewBox="0 0 100 100"><path d="M8 92C10 45 40 12 92 8 88 58 56 90 8 92Z" fill="#7cc142"/><path d="M8 92C30 66 52 44 80 22" stroke="#4a9a2c" stroke-width="3" fill="none"/></svg>{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">

{%- macro _content() -%}
<div class="gc">
	{{ leaf("gc-l1") }}{{ leaf("gc-l2") }}{{ leaf("gc-l3") }}{{ leaf("gc-l4") }}

	{#- ================= HEADER ================= -#}
	<div class="gc-head">
		{%- if header_img -%}<div class="gc-banner" style="background-image:url('{{ header_img }}')"></div>{%- endif -%}
		<div class="gc-flag"><div>CLEAN</div><div>ENERGY</div><div>BRIGHTER</div><div>TOMORROW</div></div>
		<div class="gc-brand">
			<table><tr>
				{%- if logo -%}<td class="gc-logo"><img src="{{ logo }}"></td>{%- endif -%}
				<td class="gc-names">
					<div class="gc-cname">{{ cname_main }}</div>
					{%- if cname_sub -%}<div class="gc-csub">{{ cname_sub }}</div>{%- endif -%}
				</td>
			</tr></table>
			<div class="gc-tagline">{{ tagline | replace("|", "&nbsp;&nbsp;|&nbsp;&nbsp;") }}</div>
			<table class="gc-badges"><tr>
				{%- for b in [("panel", "Solar<br>Solutions"), ("plug", "EV Charger<br>Solutions"), ("leaf", "Sustainable<br>Energy"), ("home", "For a Greener<br>Tomorrow")] -%}
				<td><table><tr><td class="gc-b-ic">{{ ic(b[0], 22, "#0d5c3a", 2) }}</td><td class="gc-b-tx">{{ b[1] }}</td></tr></table></td>
				{%- endfor -%}
			</tr></table>
		</div>
	</div>

	{#- ================= CUSTOMER / DESCRIPTION / QUOTE NO ================= -#}
	<table class="gc-info"><tr>
		<td class="gc-cust">
			<table><tr>
				<td class="gc-badge">{{ ic("user", 22, "#fff") }}</td>
				<td>
					<div class="gc-h">CUSTOMER DETAILS</div>
					<table class="gc-kv">
						<tr><td>Name</td><td>:</td><td class="gc-cust-name">{{ doc.customer_name or doc.party_name }}</td></tr>
						<tr><td>Address</td><td>:</td><td>{%- if addr_lines -%}{{ addr_lines | join("<br>") }}{%- else -%}…{%- endif -%}</td></tr>
						{%- if doc.contact_mobile -%}<tr><td>Phone</td><td>:</td><td>{{ doc.contact_mobile }}</td></tr>{%- endif -%}
					</table>
				</td>
			</tr></table>
			<table class="gc-date"><tr>
				<td class="gc-date-ic">{{ ic("cal", 24, "#1f8f3a", 2) }}</td>
				<td class="gc-date-l">DATE</td><td class="gc-date-c">:</td>
				<td class="gc-date-v">{{ frappe.utils.formatdate(doc.transaction_date, "dd/MM/yyyy") }}</td>
			</tr></table>
		</td>
		<td class="gc-desc">
			<div class="gc-desc-box">
				<div class="gc-desc-h"><span class="gc-desc-ic">{{ ic("doc", 18, "#0d5c3a") }}</span>QUOTE / PROJECT DESCRIPTION</div>
				<div class="gc-desc-tx">{{ description }}</div>
			</div>
		</td>
		<td class="gc-qno-cell">
			<div class="gc-qno">
				<div class="gc-qno-l">QUOTE NO.</div>
				<div class="gc-qno-v {{ 'gc-qno-long' if doc.name | length > 10 else '' }}">{{ doc.name }}</div>
				<div class="gc-qno-line"></div>
			</div>
		</td>
	</tr></table>

	{#- ================= DESCRIPTION / AMOUNT ================= -#}
	<table class="gc-bar"><tr><td>DESCRIPTION</td><td class="gc-bar-r">AMOUNT</td></tr></table>
	<table class="gc-main"><tr>
		<td class="gc-left">
			<div class="gc-title">{{ title | upper }}</div>
			<table class="gc-feat"><tr>
				{%- for f in [("bolt", "Reliable<br>Performance"), ("leaf", "Lower<br>Electricity Bills"), ("gear", "Sustainable<br>Future"), ("home", "Designed<br>for Your Home")] -%}
				<td><span class="gc-feat-ic">{{ ic(f[0], 22, "#1f8f3a", 2.4) }}</span><div>{{ f[1] }}</div></td>
				{%- endfor -%}
			</tr></table>
		</td>
		<td class="gc-right">
			<table class="gc-sub"><tr><td>Sub-Total</td><td class="gc-c">:</td><td class="gc-v">{{ money(subtotal) }}</td></tr></table>
			<table class="gc-pay"><tr><td>CUSTOMER PAYABLE AMOUNT</td><td class="gc-c">:</td><td class="gc-v">{{ money(payable) }}</td></tr>
				{%- if subsidy -%}<tr><td>AVAILABLE MNRE SUBSIDY</td><td class="gc-c">:</td><td class="gc-v">{{ money(subsidy) }}</td></tr>{%- endif -%}
			</table>
		</td>
	</tr></table>

	{#- ================= SIGNATURE / THANK YOU ================= -#}
	<table class="gc-sign-row"><tr>
		<td class="gc-sign">
			<div class="gc-sign-lbl">SIGNATURE</div>
			<table><tr>
				{%- if seal -%}<td class="gc-seal"><img src="{{ seal }}"></td>{%- endif -%}
				<td class="gc-sig">
					{%- if signature -%}<img src="{{ signature }}">{%- endif -%}
					<div class="gc-sig-name">{{ signatory }}</div>
					{%- if signatory_phone -%}<div class="gc-sig-phone">{{ signatory_phone }}</div>{%- endif -%}
				</td>
			</tr></table>
		</td>
		<td class="gc-thanks">
			<div class="gc-thanks-h">THANK YOU FOR YOUR BUSINESS !</div>
			<div class="gc-thanks-t">Should you have any enquiries concerning this quote, please Contact</div>
			<div class="gc-thanks-c">
				{%- if signatory -%}<span>{{ ic("phone", 16, "#1f8f3a", 2.4) }}</span><b>{{ signatory }}</b>{%- endif -%}
				{%- if signatory and signatory_phone -%}<i>|</i>{%- endif -%}
				{%- if signatory_phone -%}<span>{{ ic("phone", 16, "#1f8f3a", 2.4) }}</span><b>{{ signatory_phone }}</b>{%- endif -%}
			</div>
		</td>
	</tr></table>

	{#- ================= PAY TO / SCAN & PAY / NOTES & TERMS ================= -#}
	<table class="gc-cards"><tr>
		{%- if bank -%}
		<td class="gc-card gc-payto">
			<table class="gc-card-h"><tr><td class="gc-card-ic">{{ ic("bank", 30, "#0d5c3a", 2) }}</td><td>PAY TO:</td></tr></table>
			<table class="gc-bank">
				<tr><td>Bank</td><td>:</td><td>{{ (bank.bank or "") | upper }}</td></tr>
				{%- if bank.custom_branch -%}<tr><td>Branch</td><td>:</td><td>{{ bank.custom_branch }}</td></tr>{%- endif -%}
				<tr><td>Account Name</td><td>:</td><td>{{ (bank.account_name or company.company_name) | upper }}</td></tr>
				<tr><td>Account No</td><td>:</td><td>{{ bank.bank_account_no or "" }}</td></tr>
				{%- if bank.branch_code -%}<tr><td>IFSC Code</td><td>:</td><td>{{ bank.branch_code | upper }}</td></tr>{%- endif -%}
			</table>
		</td>
		<td class="gc-gap"></td>
		{%- endif -%}
		{%- if qr or upi -%}
		<td class="gc-card gc-qr">
			<div class="gc-qr-bank">{{ (bank.bank if bank else "") or "SCAN & PAY" }}</div>
			<div class="gc-qr-h">SCAN &amp; PAY</div>
			{%- if qr -%}<img class="gc-qr-img" src="{{ qr }}">{%- endif -%}
			{%- if upi -%}<div class="gc-qr-upi">UPI ID: {{ upi }}</div>{%- endif -%}
			<div class="gc-qr-brand">BHIM <span>|</span> UPI</div>
		</td>
		<td class="gc-gap"></td>
		{%- endif -%}
		{%- if notes or terms -%}
		<td class="gc-card gc-notes">
			<table class="gc-card-h"><tr><td class="gc-card-ic">{{ ic("doc", 28, "#0d5c3a", 2) }}</td><td>NOTES &amp; TERMS</td></tr></table>
			<ul>
				{%- for n in notes + terms -%}<li>{{ n }}</li>{%- endfor -%}
			</ul>
		</td>
		{%- endif -%}
	</tr></table>

	{#- ================= FOOTER ================= -#}
	<div class="gc-foot">
		{%- if offices -%}
		<table class="gc-offices"><tr>
			{%- for a in offices -%}
			<td class="{{ 'gc-off-first' if loop.first else '' }}">
				<table><tr>
					{%- if loop.first -%}<td class="gc-pin">{{ ic("pin", 26, "#1f8f3a", 2.4) }}</td>{%- endif -%}
					<td>
						<div class="gc-off-h">{{ (a.address_title or "Office") | upper }}</div>
						{%- if loop.first -%}<div class="gc-off-co">{{ company.company_name | upper }}</div>{%- endif -%}
						<div>{{ [a.address_line1, a.address_line2] | select | join(", ") }}</div>
						<div>{{ [a.city, a.county] | select | join(", ") }}</div>
						<div>{{ ([a.state, a.pincode] | select | join(" - ")) | upper }}</div>
					</td>
				</tr></table>
			</td>
			{%- endfor -%}
		</tr></table>
		{%- endif -%}
		<table class="gc-contact"><tr>
			{%- if company.phone_no -%}<td>{{ ic("phone", 20, "#fff") }}<span>{{ company.phone_no }}</span></td>{%- endif -%}
			{%- if signatory -%}<td>{{ ic("user", 20, "#fff") }}<span>{{ signatory }}</span></td>{%- endif -%}
			{%- if company.email -%}<td>{{ ic("mail", 20, "#fff") }}<span>{{ company.email }}</span></td>{%- endif -%}
			{%- if company.website -%}<td>{{ ic("globe", 20, "#fff") }}<span>{{ company.website | replace("https://", "") | replace("http://", "") }}</span></td>{%- endif -%}
		</tr></table>
	</div>
</div>

{%- endmacro -%}

{#- ================= EXTRA PAGES =================
    Full-page images from the Print Images tab (defaults on this Print Format's Extra Pages table,
    replaced or skipped per quotation). Each prints at its page number; the quotation page above
    takes the first free number. -#}
{%- set _xm = {} -%}
{%- for p in _pf.get("custom_extra_pages") or [] -%}{%- if p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- for p in doc.get("custom_print_extra_pages") or [] -%}{%- if p.print_format == _pf.name and p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- set _xl = [] -%}
{%- for k in _xm.keys()|sort -%}{%- if _xm[k] -%}{%- set _ = _xl.append([k, _xm[k]]) -%}{%- endif -%}{%- endfor -%}
{%- set _xn = namespace(b=0, x=0, pos=1) -%}
{%- for _i in range(1 + _xl|length) -%}
{%- if not loop.first -%}<div class="xp-brk"></div>{%- endif -%}
{%- if _xn.x < _xl|length and (_xl[_xn.x][0] <= _xn.pos or _xn.b >= 1) -%}
<div class="xp-page"><img class="xp-img" src="{{ _xl[_xn.x][1] }}"></div>
{%- set _xn.x = _xn.x + 1 -%}
{%- else -%}
{{ _content() }}
{%- set _xn.b = _xn.b + 1 -%}
{%- endif -%}
{%- set _xn.pos = _xn.pos + 1 -%}
{%- endfor -%}

{#- Right Img - 3-page Right Image solar proposal (Chrome PDF, full-bleed A4, zero margins).
    Artwork : page backgrounds ship with the app (/assets/hiper_solar/images/right_image/).
    Cover   : the page-1 middle picture is the "Cover Image" slot on the quotation's Print Images tab
              (per quotation, else this print format's slot default, else the built-in cover).
    Extra pages : full-page images from the Print Images tab print at their page numbers;
              this format's own 3 pages fill the remaining numbers in order.
    Layout is authored on the original 1240 x 1635 px artwork grid, printed full-bleed on A4. -#}
{%- macro num(s) -%}
{%- set ns = namespace(n="", on=false, done=false) -%}
{%- for ch in (s or "")|string -%}{%- if not ns.done -%}
{%- if ch in "0123456789." -%}{%- set ns.n = ns.n ~ ch -%}{%- set ns.on = true -%}{%- elif ns.on -%}{%- set ns.done = true -%}{%- endif -%}
{%- endif -%}{%- endfor -%}{{ ns.n.strip(".") }}
{%- endmacro -%}
{%- macro num_before_kw(s) -%}
{%- set u = (s or "")|string|upper -%}{%- set i = u.find("KW") -%}
{%- if i > 0 -%}{%- set seg = u[:i]|trim -%}{%- set ns = namespace(n="") -%}
{%- for ch in seg|reverse -%}{%- if ns.n is not none -%}{%- if ch in "0123456789." -%}{%- set ns.n = ch ~ ns.n -%}{%- else -%}{%- set ns.n = none -%}{%- endif -%}{%- endif -%}{%- endfor -%}
{{- (ns.n if ns.n is not none else "")|string -}}
{%- endif -%}
{%- endmacro -%}
{%- macro nice(x) -%}{%- set f = x|float -%}{{ (f|int) if f == (f|int) else f }}{%- endmacro -%}
{%- macro url(p) -%}{%- if p -%}{{ p if p.startswith("http") else frappe.utils.get_url(p) }}{%- endif -%}{%- endmacro -%}

{#- ---------- data ---------- -#}
{%- set _pf = frappe.get_doc("Print Format", "Right Img") -%}
{%- set img = {} -%}
{%- for sl in _pf.get("custom_image_slots") or [] -%}{%- if sl.default_image -%}{%- set _ = img.update({sl.label: sl.default_image}) -%}{%- endif -%}{%- endfor -%}
{%- for r in doc.get("custom_print_images") or [] -%}{%- if r.print_format == _pf.name and r.image -%}{%- set _ = img.update({r.slot: r.image}) -%}{%- endif -%}{%- endfor -%}
{%- set _asset = "/assets/hiper_solar/images/right_image/" -%}
{%- set img1 = url(_asset ~ "page1.jpg") -%}
{%- set imgc = url(img.get("Cover Image") or (_asset ~ "cover.jpg")) -%}
{%- set img2 = url(_asset ~ "page2.jpg") -%}
{%- set img3 = url(_asset ~ "page3.jpg") -%}
{%- set cap_s = num(doc.custom_total_capacity) -%}
{%- set cap = (cap_s|float) if cap_s else 0 -%}

{%- set it = namespace(panel=none, inverter=none) -%}
{%- for row in doc.items -%}
  {%- if row.item_group == "Panel" and not it.panel -%}{%- set it.panel = row -%}{%- endif -%}
  {%- if row.item_group == "Inverter" and not it.inverter -%}{%- set it.inverter = row -%}{%- endif -%}
{%- endfor -%}
{%- set inv_s = num_before_kw(it.inverter.item_name) if it.inverter else "" -%}
{%- set inv = (inv_s|float) if inv_s else cap -%}
{%- set inv_brand = ((it.inverter.custom_print_make or it.inverter.brand or (it.inverter.item_name or "").split(" ")[0]) if it.inverter else "") -%}

{%- set has_crm = frappe.db.exists("DocType", "CRM Lead") -%}
{%- set crm_lead = doc.party_name if doc.quotation_to == "CRM Lead" else ((frappe.db.get_value("Customer", doc.party_name, "custom_crm_lead") if frappe.get_meta("Customer").has_field("custom_crm_lead") else none) if doc.quotation_to == "Customer" else none) -%}
{%- set place = frappe.db.get_value("Address", doc.customer_address, "city") if doc.customer_address else none -%}
{%- if not place and crm_lead and has_crm and frappe.get_meta("CRM Lead").has_field("custom_location") -%}{%- set place = frappe.db.get_value("CRM Lead", crm_lead, "custom_location") -%}{%- endif -%}
{%- set salutation = frappe.db.get_value("Contact", doc.contact_person, "salutation") if doc.contact_person else none -%}
{%- if not salutation and crm_lead and has_crm -%}{%- set salutation = frappe.db.get_value("CRM Lead", crm_lead, "salutation") -%}{%- endif -%}
{%- set who = ((salutation ~ ". ") if salutation and not salutation.endswith(".") else ((salutation ~ " ") if salutation else "")) ~ (doc.customer_name or doc.party_name) ~ ((" - " ~ place) if place else "") -%}
{%- set bar_len = (who|length) + 14 -%}
{%- set bar_px = 64 if bar_len <= 43 else (64 * 43 / bar_len)|round(0, "floor")|int -%}

{%- set d = frappe.utils.getdate(doc.transaction_date) -%}
{%- set total = doc.rounded_total or doc.grand_total -%}
{%- set words = (doc.in_words or "")|replace("INR ", "")|replace("₹ ", "") -%}
{%- set words = words[:-1] if words.endswith(".") else words -%}

{%- if doc.custom_subsidy_amount -%}{%- set subsidy = doc.custom_subsidy_amount -%}
{%- elif cap <= 0 -%}{%- set subsidy = 0 -%}
{%- elif cap <= 2 -%}{%- set subsidy = 30000 * cap -%}
{%- elif cap <= 3 -%}{%- set subsidy = 60000 + 18000 * (cap - 2) -%}
{%- else -%}{%- set subsidy = 78000 -%}{%- endif -%}

{%- set particulars = doc.custom_price_particulars or (
    "Supply and Installation of " ~ nice(cap) ~ " KW Ongrid Solar Power Plant"
    ~ ((" with " ~ (it.panel.description|striptags|trim if it.panel.description else it.panel.item_name)) if it.panel else "")
    ~ ((", " ~ nice(inv) ~ " KW " ~ (inv_brand|title) ~ " Inverter") if it.inverter else "")
    ~ " and all accessories. (Including GST)") -%}

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,700..900&family=Montserrat:wght@600;700&family=Open+Sans:wdth,wght@75..100,400..700&display=block" rel="stylesheet">
<style>
  @page { size: A4; margin: 0; }
  html, body { margin: 0 !important; padding: 0 !important; background: #fff; }
  .print-format { padding: 0 !important; margin: 0 !important; width: auto !important; max-width: none !important; min-height: 0 !important; box-shadow: none !important; }
  .ri-page { position: relative; width: 210mm; height: 296.9mm; overflow: hidden; background: #fff; }
  .ri-brk { break-before: page; page-break-before: always; }
  .ri-xp { width: 100%; height: 100%; object-fit: contain; display: block; }
  /* Full-bleed A4: 1240px artwork grid -> 210mm wide; artwork stretched vertically x1.0726 to fill 297mm (text is not stretched) */
  .ri-stage { position: absolute; left: 0; top: 0; width: 1240px; height: 1754px; zoom: 0.640081; }
  .ri-bg { position: absolute; left: 0; top: 0; width: 1240px; height: 1754px; display: block; object-fit: fill; }
  .ri-abs { position: absolute; white-space: nowrap; }
  .ri-os { font-family: "Open Sans", Arial, sans-serif; }
  .ri-hd { font-family: "Archivo", "Arial Black", Arial, sans-serif; font-weight: 900; font-stretch: 86%; letter-spacing: -0.5px; }
  .ri-sp { font-family: "Montserrat", Arial, sans-serif; font-weight: 600; letter-spacing: 3px; text-transform: uppercase; color: #1b1b1b; }
  .ri-orange { color: #f4520a; }

  /* page 1 */
  .ri-year { left: 805px; top: 204px; font: 600 114px/120px "Open Sans", Arial, sans-serif; color: #fff; letter-spacing: -1px; }
  .ri-bar { left: 0; top: 361px; width: 1240px; height: 153px; display: flex; align-items: center; justify-content: center; font-family: "Open Sans", Arial, sans-serif; font-weight: 700; font-stretch: 82%; color: #fff; letter-spacing: 0; }
  .ri-bar b { color: #fbd01c; font-weight: 700; }
  .ri-cover { position: absolute; left: 0; top: 515px; width: 1240px; height: 860px; object-fit: fill; display: block; }
  .ri-ref { left: 830px; top: 1493px; font: 600 39px/64px "Open Sans", Arial, sans-serif; font-stretch: 78%; color: #141414; letter-spacing: -0.3px; }

  /* page 2 */
  .ri-t2a { left: 270px; top: 484px; font-size: 64px; line-height: 64px; font-stretch: 80%; letter-spacing: 0; }
  .ri-t2b { left: 270px; top: 547px; font-size: 25px; line-height: 32px; }
  .ri-tblwrap { position: absolute; left: 50px; top: 692px; width: 1145px; }
  .ri-tbl { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; font-family: "Open Sans", Arial, sans-serif; font-size: 23px; line-height: 28px; color: #2a2a2a; }
  .ri-tbl th { background: #034079; color: #fff; font-weight: 700; font-size: 25px; height: 52px; padding: 0 22px; text-align: center; }
  .ri-tbl th:first-child { text-align: left; border-top-left-radius: 12px; }
  .ri-tbl th:last-child { border-top-right-radius: 12px; }
  .ri-tbl td { padding: 9px 22px; height: 44px; vertical-align: middle; border-right: 1.5px solid #b9cbe2; border-bottom: 1.5px solid #b9cbe2; background: #fff; overflow-wrap: normal; word-break: normal; hyphens: none; }
  .ri-tbl td:first-child { border-left: 1.5px solid #b9cbe2; }
  .ri-tbl tr:nth-child(even) td { background: #eef5fc; }
  .ri-tbl td.c { text-align: center; padding-left: 6px; padding-right: 6px; }
  .ri-tbl td.m { padding-left: 24px; padding-right: 8px; }
  .ri-tbl td.w { padding-left: 28px; padding-right: 10px; }
  .ri-tbl tr:last-child td:first-child { border-bottom-left-radius: 12px; }
  .ri-tbl tr:last-child td:last-child { border-bottom-right-radius: 12px; }

  /* page 3 */
  .ri-t3a { left: 318px; top: 386px; font-size: 60px; line-height: 64px; font-stretch: 78%; letter-spacing: 0; }
  .ri-t3a small { font-size: 42px; }
  .ri-part { left: 100px; top: 618px; width: 735px; height: 150px; display: flex; align-items: center; white-space: normal; font: 400 27px/38px "Open Sans", Arial, sans-serif; color: #2b2b2b; }
  .ri-price { left: 846px; top: 614px; width: 342px; height: 157px; display: flex; align-items: center; justify-content: center; font: 400 31px/1 "Open Sans", Arial, sans-serif; color: #222; }
  .ri-total { left: 846px; top: 770px; width: 342px; height: 85px; display: flex; align-items: center; justify-content: center; font: 700 38px/1 "Open Sans", Arial, sans-serif; color: #0d1b33; letter-spacing: -0.5px; }
  .ri-words { left: 233px; top: 944px; width: 945px; font: 500 31px/44px "Open Sans", Arial, sans-serif; color: #1e1e1e; overflow: hidden; text-overflow: ellipsis; }
  .ri-subsidy { left: 578px; top: 1358px; height: 112px; line-height: 112px; font-size: 94px; font-stretch: 84%; color: #0b2a63; letter-spacing: 0; }
</style>

{#- ================= PAGE 1 : cover ================= -#}
{%- macro _page1() -%}
<div class="ri-stage">
  {%- if img1 %}<img class="ri-bg" src="{{ img1 }}">{% endif %}
  {%- if imgc %}<img class="ri-cover" src="{{ imgc }}">{% endif %}
  <div class="ri-abs ri-year">{{ d.year }}</div>
  <div class="ri-abs ri-bar" style="font-size: {{ bar_px }}px;">Quotation for&nbsp;<b>{{ who }}</b></div>
  <div class="ri-abs ri-ref">Ref: {{ doc.name }}<br>Date:{{ d.strftime("%d.%m.%Y") }}</div>
</div>
{%- endmacro -%}

{#- ================= PAGE 2 : products & specifications ================= -#}
{%- macro _page2() -%}
<div class="ri-stage">
  {%- if img2 %}<img class="ri-bg" src="{{ img2 }}">{% endif %}
  <div class="ri-abs ri-hd ri-orange ri-t2a">{{ nice(cap) }} KW SOLAR GRID TIE SYSTEM</div>
  <div class="ri-abs ri-sp ri-t2b">WITH {{ nice(inv) }} KW STRING INVERTER</div>
  <div class="ri-tblwrap">
    <table class="ri-tbl">
      <colgroup><col style="width:450px"><col style="width:152px"><col style="width:273px"><col style="width:270px"></colgroup>
      <thead><tr><th>Materials</th><th>Qty</th><th>Make</th><th>Warranty</th></tr></thead>
      <tbody>
      {%- for row in doc.items %}
        {%- set desc = (row.description|striptags|trim) if row.description else "" -%}
        <tr>
          <td>{{ desc or row.item_name }}</td>
          <td class="c">{{ row.custom_print_qty or nice(row.qty) }}</td>
          <td class="m">{{ (row.custom_print_make or row.brand or "")|upper }}</td>
          <td class="w">{{ (row.custom_warranty or "")|upper }}</td>
        </tr>
      {%- endfor %}
      {%- if cap %}
        <tr>
          <td>PRODUCTION</td>
          <td class="c">&ndash;</td>
          <td class="m"></td>
          <td class="w">{{ nice((cap * 4)|round(1)) }} UNITS PER DAY SUBJECT TO SUNLIGHT</td>
        </tr>
      {%- endif %}
      </tbody>
    </table>
  </div>
</div>
{%- endmacro -%}

{#- ================= PAGE 3 : pricing ================= -#}
{%- macro _page3() -%}
<div class="ri-stage">
  {%- if img3 %}<img class="ri-bg" src="{{ img3 }}">{% endif %}
  <div class="ri-abs ri-hd ri-orange ri-t3a">{{ nice(cap) }} kW PANEL <small>WITH</small> {{ nice(inv) }} kW INVERTER</div>
  <div class="ri-abs ri-part">{{ particulars }}</div>
  <div class="ri-abs ri-price">{{ frappe.utils.fmt_money(total, 2, None, "#,##,###.##") }}</div>
  <div class="ri-abs ri-total">{{ frappe.utils.fmt_money(total, 0, None, "#,##,###.##") }}/-</div>
  <div class="ri-abs ri-words">({{ words }})</div>
  {%- if subsidy %}<div class="ri-abs ri-hd ri-subsidy">{{ subsidy|int }} /-</div>{% endif %}
</div>
{%- endmacro -%}

{#- ================= PAGE ORDER + EXTRA PAGES =================
    Extra pages: defaults on this Print Format's Extra Pages table, replaced or skipped per quotation.
    Each prints at its page number; the format's own pages take the free numbers in order. -#}
{%- set _xm = {} -%}
{%- for p in _pf.get("custom_extra_pages") or [] -%}{%- if p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- for p in doc.get("custom_print_extra_pages") or [] -%}{%- if p.print_format == _pf.name and p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- set _xl = [] -%}
{%- for k in _xm.keys()|sort -%}{%- if _xm[k] -%}{%- set _ = _xl.append([k, _xm[k]]) -%}{%- endif -%}{%- endfor -%}
{%- set _xn = namespace(b=0, x=0, pos=1) -%}
{%- for _i in range(3 + _xl|length) -%}
<div class="ri-page{{ ' ri-brk' if not loop.first else '' }}">
{%- if _xn.x < _xl|length and (_xl[_xn.x][0] <= _xn.pos or _xn.b >= 3) -%}
<img class="ri-xp" src="{{ url(_xl[_xn.x][1]) }}">
{%- set _xn.x = _xn.x + 1 -%}
{%- else -%}
{%- if _xn.b == 0 -%}{{ _page1() }}{%- elif _xn.b == 1 -%}{{ _page2() }}{%- else -%}{{ _page3() }}{%- endif -%}
{%- set _xn.b = _xn.b + 1 -%}
{%- endif -%}
</div>
{%- set _xn.pos = _xn.pos + 1 -%}
{%- endfor -%}
